<script setup lang="ts">
import type { ApiProblem } from '~/types/api'; import type { GradeInput } from '~/composables/useGrades'
const props = defineProps<{ offeringId: number }>(); const { list, save } = useGrades(); const { data: enrollments } = await useAsyncData(`grades-${props.offeringId}`, () => list(props.offeringId)); const rows = ref((enrollments.value ?? []).map(item => ({ enrollment_id: item.id, student: `${item.student?.last_name}, ${item.student?.first_name}`, number: item.student?.student_number, midterm_grade: item.grade?.midterm_grade ?? null, final_grade: item.grade?.final_grade ?? null, remarks: item.grade?.remarks ?? null }))); const dirty = ref(false); const saving = ref(false); const errorMessage = ref('')
async function submit() { saving.value = true; errorMessage.value = ''; try { await save(props.offeringId, rows.value.map(({ enrollment_id, midterm_grade, final_grade, remarks }) => ({ enrollment_id, midterm_grade: midterm_grade === null ? null : Number(midterm_grade), final_grade: final_grade === null ? null : Number(final_grade), remarks: remarks || null } as GradeInput))); dirty.value = false } catch (error) { errorMessage.value = (error as ApiProblem).message } finally { saving.value = false } }
</script>
<template><div><div class="mb-4 flex justify-end"><BaseButton :disabled="!dirty" :loading="saving" @click="submit">Save grades</BaseButton></div><p v-if="errorMessage" class="mb-4 text-sm text-red-600">{{ errorMessage }}</p><BaseCard :padded="false"><div class="overflow-x-auto"><table class="w-full min-w-[700px] text-left text-sm"><thead class="bg-[#f1f5f9] text-[#52677f]"><tr><th class="p-4 font-semibold">Student</th><th class="p-4 font-semibold">Midterm</th><th class="p-4 font-semibold">Final</th><th class="p-4 font-semibold">Remarks</th></tr></thead><tbody><tr v-for="row in rows" :key="row.enrollment_id" class="border-t border-[#e5ecf3]"><td class="p-4 text-[#29445f]"><strong>{{ row.student }}</strong><small class="block text-[#60728a]">{{ row.number }}</small></td><td class="p-4"><input v-model="row.midterm_grade" class="field-control" type="number" min="1" max="5" step="0.01" @input="dirty = true"></td><td class="p-4"><input v-model="row.final_grade" class="field-control" type="number" min="1" max="5" step="0.01" @input="dirty = true"></td><td class="p-4"><select v-model="row.remarks" class="field-control" @change="dirty = true"><option :value="null">Not set</option><option v-for="value in ['passed', 'failed', 'incomplete', 'dropped']" :key="value" :value="value">{{ value }}</option></select></td></tr></tbody></table></div></BaseCard></div></template>
